def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                grid[ny][nx] != 0 and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            components.append(cells)

    components.sort(key=len, reverse=True)
    a, b = components[:2]

    def box(cells):
        return (min(r for r, c in cells), min(c for r, c in cells),
                max(r for r, c in cells), max(c for r, c in cells))

    ar0, ac0, ar1, ac1 = box(a)
    br0, bc0, br1, bc1 = box(b)
    rows, cols = ar1 - ar0 + 1, ac1 - ac0 + 1

    diff = []
    for r in range(rows):
        line = []
        for c in range(cols):
            line.append(8 if grid[ar0 + r][ac0 + c] != grid[br0 + r][bc0 + c] else 0)
        diff.append(line)

    active = [r for r, line in enumerate(diff) if any(line)]
    if not active:
        return [[0]]
    return diff[active[0]:active[-1] + 1]
